using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
using FogEnvironment=Godot.Environment;
public partial class FogEnvironmentOperations:RefCounted
{
    private readonly FogGroundSamplerOperations _ground=new();private readonly FogCloudShadowOperations _shadow=new();
    private static FogEnvironment? Env(Node owner,string key)=>owner.Get(key).As<FogEnvironment>();private static Viewport View(Node owner)=>owner.GetViewport();private static GArray List(Node owner,string key)=>owner.Get(key).AsGodotArray();
    private static void Disconnect(GodotObject? source,string signal,Callable callback){if(source!=null&&GodotObject.IsInstanceValid(source)&&source.IsConnected(signal,callback))source.Disconnect(signal,callback);}
    public void ready(Node owner){foreach(var light in View(owner).FindChildren("*","Light3D",true,false))light_added(owner,light);owner.GetTree().Connect(SceneTree.SignalName.NodeAdded,new Callable(owner,"_light_added"));}
    public void light_added(Node owner,Node node){if(node is Light3D light&&light.IsInsideTree()&&light.GetWorld3D()==owner.Get("world").As<World3D>())List(owner,"lights").Add(GodotObject.WeakRef(light)!);}
    public void sync_shadow_buffers(Node owner)
    {
        var viewport=View(owner);long resize=owner.Get("resize_frame").AsInt64();float temporary=owner.Get("temporary_scale").AsSingle();if(resize>=0&&(long)Engine.GetProcessFrames()>resize){if(Mathf.IsEqualApprox(viewport.Get("scaling_3d_scale").AsSingle(),temporary))viewport.Set("scaling_3d_scale",owner.Get("original_scale"));owner.Set("resize_frame",-1);}var enabled=new List<long>();var lights=List(owner,"lights");for(int i=lights.Count-1;i>=0;i--){var light=lights[i].As<WeakRef>().GetRef().As<Light3D>();if(light==null){lights.RemoveAt(i);continue;}if(light.ShadowEnabled&&light.IsVisibleInTree())enabled.Add(unchecked((long)light.GetInstanceId()));}enabled.Sort();long signature=GD.Hash(new GArray{enabled.ToArray(),viewport.Get("positional_shadow_atlas_size"),viewport.Get("positional_shadow_atlas_16_bits")});if(signature==owner.Get("shadow_signature").AsInt64())return;owner.Set("shadow_signature",signature);if(enabled.Count==0)return;if(owner.Get("resize_frame").AsInt64()<0){float original=viewport.Get("scaling_3d_scale").AsSingle();var size=viewport.Get("size").AsVector2I();float change=2f/Math.Max(64,Math.Min(size.X,size.Y));temporary=Math.Clamp(original>.15f?original-change:original+change,.1f,2);owner.Set("original_scale",original);owner.Set("temporary_scale",temporary);viewport.Set("scaling_3d_scale",temporary);owner.Set("resize_frame",unchecked((long)Engine.GetProcessFrames()));}
    }
    public void attach(Node runtime)
    {
        var viewport=runtime.GetViewport();var coordinator=viewport.GetNodeOrNull<Node>("KiwiFogEnvironment");if(coordinator==null){coordinator=GD.Load<GDScript>("res://scripts/actors/fog/fog_environment.gd").New().As<Node>();coordinator.Name="KiwiFogEnvironment";coordinator.Set("world",viewport.FindWorld3D());coordinator.ProcessPriority=100;viewport.AddChild(coordinator);}List(coordinator,"entries").Add(GodotObject.WeakRef(runtime)!);
    }
    public long environment_signature(FogEnvironment? environment)
    {
        if(environment==null)return 0;var script=GD.Load<GDScript>("res://scripts/actors/fog/fog_environment.gd");var keys=script.Get("environment_keys").AsStringArray();if(keys.Length==0){var found=new List<string>();foreach(var info in environment.GetPropertyList()){string name=info["name"].AsString();if((info["usage"].AsInt64()&(long)PropertyUsageFlags.Storage)!=0&&!name.StartsWith("resource_",StringComparison.Ordinal))found.Add(name);}keys=found.ToArray();script.Set("environment_keys",keys);}var values=new GArray();foreach(string key in keys)values.Add(environment.Get(key));return GD.Hash(values);
    }
    public void process(Node owner,double delta)
    {
        var world=owner.Get("world").As<World3D>();if(world==null)return;var active=new List<Node>();var globals=new List<Node>();var entries=List(owner,"entries");for(int i=entries.Count-1;i>=0;i--){var runtime=entries[i].As<WeakRef>().GetRef().As<Node>();if(runtime==null){entries.RemoveAt(i);continue;}if(!runtime.Get("active").AsBool()){runtime.Get("content").As<Node>().GetNodeOrNull<Decal>("KiwiCloudShadow")?.Hide();continue;}active.Add(runtime);if(runtime.Get("actor").As<Resource>().Get("type_id").AsString()=="global_fog")globals.Add(runtime);}globals.Sort((a,b)=>StringComparer.Ordinal.Compare(a.Get("actor").As<Resource>().Get("id").AsString(),b.Get("actor").As<Resource>().Get("id").AsString()));DirectionalLight3D? sun=null;float energy=0;foreach(var value in List(owner,"lights")){var candidate=value.As<WeakRef>().GetRef().As<DirectionalLight3D>();if(candidate!=null&&candidate.IsVisibleInTree()&&candidate.LightEnergy*candidate.LightVolumetricFogEnergy>energy){sun=candidate;energy=candidate.LightEnergy*candidate.LightVolumetricFogEnergy;}}var viewport=View(owner);var camera=viewport.GetCamera3D();bool capture=viewport.GetMeta("kiwi_scene_frame_capture",false).AsBool();foreach(var runtime in active){var fog=runtime.Get("content").As<FogVolume>();var material=fog.Material as ShaderMaterial;double time=runtime.Get("actor").As<Resource>().Get("animation_time").AsDouble();_shadow.sync(runtime,sun,double.IsNaN(time)?0:time,capture);if(material==null||material.Shader!=GD.Load<Shader>("res://scripts/actors/fog/fog_surface.gdshader"))continue;_ground.sync(runtime,material);material.SetShaderParameter("sun_direction",sun!=null?sun.GlobalBasis.Z.Normalized():Vector3.Up);material.SetShaderParameter("sun_color",sun!=null?sun.LightColor*energy:Colors.Black);material.SetShaderParameter("viewer_position",camera!=null?camera.GlobalPosition:Vector3.Zero);}for(int i=0;i<globals.Count;i++)globals[i].Get("content").As<Node3D>().Visible=i==0;
        var overlay=Env(owner,"overlay");var source=Env(owner,"source");if(active.Count==0){RestoreScale(owner);restore_camera(owner);if(world.Environment==overlay)world.Environment=source;return;}if(world.Environment!=overlay){if(source!=world.Environment){Disconnect(source,"changed",new Callable(owner,"_dirty"));source=world.Environment;owner.Set("source",source!=null?Variant.From(source):default);if(source!=null)source.Connect(Resource.SignalName.Changed,new Callable(owner,"_dirty"));}owner.Set("source_dirty",true);}long signature=environment_signature(source);if(signature!=owner.Get("source_signature").AsInt64()){owner.Set("source_signature",signature);owner.Set("source_dirty",true);}if(owner.Get("source_dirty").AsBool()||overlay==null){overlay=source?.Duplicate() as FogEnvironment??new FogEnvironment();owner.Set("overlay",overlay);owner.Set("source_dirty",false);}overlay.Set("volumetric_fog_enabled",true);overlay.Set("volumetric_fog_temporal_reprojection_enabled",!capture&&(source?.Get("volumetric_fog_temporal_reprojection_enabled").AsBool()??true));overlay.Set("volumetric_fog_density",globals.Count>0?0:source?.Get("volumetric_fog_density").AsDouble()??0);world.Environment=overlay;sync_camera(owner,globals.Count>0);sync_shadow_buffers(owner);
    }
    private static void RestoreScale(Node owner){if(owner.Get("resize_frame").AsInt64()<0)return;var viewport=View(owner);if(Mathf.IsEqualApprox(viewport.Get("scaling_3d_scale").AsSingle(),owner.Get("temporary_scale").AsSingle()))viewport.Set("scaling_3d_scale",owner.Get("original_scale"));owner.Set("resize_frame",-1);}
    public void sync_camera(Node owner,bool globalFog)
    {
        var camera=View(owner).GetCamera3D();var weak=owner.Get("camera_ref").As<WeakRef>();var previous=weak?.GetRef().As<Camera3D>();if(camera!=previous)restore_camera(owner);if(camera==null||camera.Environment==null)return;if(owner.Get("camera_ref").VariantType==Variant.Type.Nil)owner.Set("camera_ref",GodotObject.WeakRef(camera)!);var source=Env(owner,"camera_source");var overlay=Env(owner,"camera_overlay");if(camera.Environment!=overlay&&source!=camera.Environment){Disconnect(source,"changed",new Callable(owner,"_camera_changed"));source=camera.Environment;owner.Set("camera_source",source);source.Connect(Resource.SignalName.Changed,new Callable(owner,"_camera_changed"));owner.Set("camera_dirty",true);}long signature=environment_signature(source);if(signature!=owner.Get("camera_signature").AsInt64()){owner.Set("camera_signature",signature);owner.Set("camera_dirty",true);}if(owner.Get("camera_dirty").AsBool()||overlay==null){overlay=(FogEnvironment)source!.Duplicate();owner.Set("camera_overlay",overlay);owner.Set("camera_dirty",false);}overlay.Set("volumetric_fog_enabled",true);overlay.Set("volumetric_fog_density",globalFog?0:source!.Get("volumetric_fog_density").AsDouble());camera.Environment=overlay;overlay.Set("volumetric_fog_temporal_reprojection_enabled",!View(owner).GetMeta("kiwi_scene_frame_capture",false).AsBool()&&source!.Get("volumetric_fog_temporal_reprojection_enabled").AsBool());
    }
    public void restore_camera(Node owner){var camera=owner.Get("camera_ref").As<WeakRef>()?.GetRef().As<Camera3D>();var source=Env(owner,"camera_source");if(camera!=null&&camera.Environment==Env(owner,"camera_overlay"))camera.Environment=source;Disconnect(source,"changed",new Callable(owner,"_camera_changed"));owner.Set("camera_ref",default(Variant));owner.Set("camera_source",default(Variant));owner.Set("camera_overlay",default(Variant));owner.Set("camera_dirty",true);owner.Set("camera_signature",0);}
    public void exit_tree(Node owner){Disconnect(owner.GetTree(),SceneTree.SignalName.NodeAdded,new Callable(owner,"_light_added"));RestoreScale(owner);restore_camera(owner);var world=owner.Get("world").As<World3D>();var source=Env(owner,"source");if(world!=null&&world.Environment==Env(owner,"overlay"))world.Environment=source;Disconnect(source,"changed",new Callable(owner,"_dirty"));}
}
